'use strict';
let rateconDBPromise=null,rateconDocs=[],reviewingRatecon=null,rateconURLs=[];
window.activeRateconId=null;
function rateconDB(){if(!rateconDBPromise)rateconDBPromise=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('Document storage is unavailable in this browser.'));return}const r=indexedDB.open('sagisolar-documents',1);r.onupgradeneeded=()=>r.result.createObjectStore('ratecons',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not open document storage.'));r.onblocked=()=>reject(Error('Close other SagiSolar tabs and retry.'));});return rateconDBPromise;}
async function docOp(mode,action){const db=await rateconDB();return new Promise((resolve,reject)=>{const tx=db.transaction('ratecons',mode),request=action(tx.objectStore('ratecons'));let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error('Could not save or read the document. Browser storage may be full.'));tx.onabort=()=>reject(Error('Document storage was interrupted.'));});}
function fileURL(doc){const u=URL.createObjectURL(doc.blob);rateconURLs.push(u);return u;}
function openDocument(doc){const a=document.createElement('a');a.href=fileURL(doc);a.target='_blank';a.rel='noopener';a.click();}
window.setActiveRatecon=function(id,name){window.activeRateconId=id;$('activeRateconLabel').textContent=id?`Attached: ${name||rateconDocs.find(d=>d.id===id)?.name||'Rate confirmation'}`:'PDF or photo · attach it to your estimate';$('detachRatecon').hidden=!id;};$('detachRatecon').onclick=()=>window.setActiveRatecon(null);
async function pdfText(bytes){const lib=await import('./vendor/pdf.min.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.mjs',location.href).href;const task=lib.getDocument({data:new Uint8Array(bytes),isEvalSupported:false,useSystemFonts:true});let timer;try{return await Promise.race([(async()=>{const pdf=await task.promise;let text='';const count=Math.min(pdf.numPages,20);for(let i=1;i<=count;i++){const page=await pdf.getPage(i),content=await page.getTextContent();let y=null;for(const item of content.items){if(!('str'in item))continue;if(y!==null&&Math.abs(item.transform[5]-y)>3)text+='\n';text+=item.str+(item.hasEOL?'\n':' ');y=item.hasEOL?null:item.transform[5];}text+='\n';if(text.length>100000){text=text.slice(0,100000);break;}}return{text,note:pdf.numPages>20?'Only the first 20 pages were read. Review the full original.':''};})(),new Promise((_,reject)=>timer=setTimeout(()=>reject(Error('Text reading timed out.')),20000))]);}finally{clearTimeout(timer);await task.destroy();}}
$('rateconFile').onchange=async()=>{const file=$('rateconFile').files[0];if(!file)return;$('rateconReview').hidden=true;if(file.size>10*1024*1024){$('rateconStatus').textContent='Choose a file no larger than 10 MB.';return}$('rateconFile').disabled=true;$('rateconStatus').textContent='Checking and saving your document…';try{const all=await docOp('readonly',s=>s.getAll());if(all.reduce((n,d)=>n+d.size,0)+file.size>50*1024*1024)throw Error('This app limits documents to 50 MB on this device. Remove an older document first.');const bytes=await file.arrayBuffer(),type=RateconCore.detectType(new Uint8Array(bytes));if(!type)throw Error('Choose a valid PDF, JPG, PNG or WebP file. HEIC photos must be converted first.');const doc={id:crypto.randomUUID(),name:file.name.slice(0,200),size:file.size,type,blob:new Blob([bytes],{type}),createdAt:new Date().toISOString(),text:'',note:'Photo attached. Automatic text reading is not available for images; enter the details below.',fields:{}};await docOp('readwrite',s=>s.put(doc));$('rateconStatus').textContent=type==='application/pdf'?'Document saved. Reading PDF text…':'Photo saved on this device.';if(type==='application/pdf'){try{const r=await pdfText(bytes);doc.text=r.text;doc.note=r.text.trim()?'Suggested fields may be incomplete or incorrect. Check every value against the original. '+r.note:'No readable text was found. This may be a scanned PDF. Enter the load details manually.';doc.fields=RateconCore.suggest(doc.text);}catch{doc.note='Document saved, but its text could not be read. It may be scanned, password-protected, or unsupported by this browser. Open the original and enter details manually.';}await docOp('readwrite',s=>s.put(doc));}await renderRatecons();showRatecon(doc);$('rateconStatus').textContent='Saved on this device. Review the details below.';}catch(e){$('rateconStatus').textContent=e.message;}finally{$('rateconFile').disabled=false;$('rateconFile').value='';}};
function showRatecon(doc){reviewingRatecon=doc;for(const k of ['loadNumber','pay','origin','destination','miles'])$('rc_'+k).value=doc.fields[k]??'';$('extractionNote').textContent=doc.note;$('rateconText').textContent=doc.text||'No text extracted. View the original document.';$('confirmRatecon').checked=false;$('rateconImage').innerHTML=doc.type.startsWith('image/')?`<img src="${fileURL(doc)}" alt="Uploaded rate confirmation for review">`:'';$('rateconReview').hidden=false;$('openCurrentRatecon').onclick=()=>openDocument(doc);}
$('rateconForm').onsubmit=async e=>{e.preventDefault();if(!reviewingRatecon)return;const fields={};['loadNumber','pay','origin','destination','miles'].forEach(k=>fields[k]=$('rc_'+k).value.trim());try{const updated={...reviewingRatecon,fields};await docOp('readwrite',s=>s.put(updated));reviewingRatecon=updated;const fuelPrice=$('price').value;$('tripForm').reset();$('price').value=fuelPrice;for(const k of ['origin','destination','pay','miles'])$(k).value=fields[k];window.setActiveRatecon(updated.id,updated.name);last=null;$('result').innerHTML='<h2>Rate confirmation attached.</h2><p>Confirm loaded and empty miles, trip duration, fuel price and fees, then calculate your trip.</p>';tab('plan');toast('Reviewed details copied. Calculate and save to retain the trip link.');}catch(e){toast(e.message)}};
async function renderRatecons(){try{rateconDocs=(await docOp('readonly',s=>s.getAll())).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('rateconList').innerHTML=rateconDocs.map(d=>`<article class="trip-card document-item"><h3 class="document-title">${esc(d.name)}</h3><small>${new Date(d.createdAt).toLocaleDateString()} · ${(d.size/1024/1024).toFixed(2)} MB · ${d.type==='application/pdf'?'PDF':'Photo'}${d.fields.loadNumber?' · Load '+esc(d.fields.loadNumber):''}</small><div class="actions"><button data-review="${d.id}">Review & use</button><button data-open="${d.id}">Open original ↗</button><a href="${fileURL(d)}" download="${esc(d.name)}">Download</a><button class="text-button" data-delete="${d.id}">Remove document</button></div><label>Attach to an existing saved trip<select data-attach="${d.id}"><option value="">Choose a saved trip</option>${saved.map(s=>`<option value="${s.id}">${esc(tripLabel(s))}${s.rateconId===d.id?' · Attached':''}</option>`).join('')}</select></label><small>${saved.filter(s=>s.rateconId===d.id).length} saved trip(s) linked</small></article>`).join('')||'<div class="card">No rate confirmations uploaded yet.</div>';
 for(const b of $('rateconList').querySelectorAll('[data-review]'))b.onclick=()=>{showRatecon(rateconDocs.find(d=>d.id===b.dataset.review));$('rateconReview').scrollIntoView({behavior:'smooth',block:'start'});};for(const b of $('rateconList').querySelectorAll('[data-open]'))b.onclick=()=>openDocument(rateconDocs.find(d=>d.id===b.dataset.open));
 for(const select of $('rateconList').querySelectorAll('[data-attach]'))select.onchange=()=>{if(!select.value)return;const trip=saved.find(s=>String(s.id)===select.value);if(trip.rateconId&&trip.rateconId!==select.dataset.attach&&!confirm('Replace the document attached to this saved trip?')){select.value='';return}const next=saved.map(s=>String(s.id)===select.value?{...s,rateconId:select.dataset.attach}:s);if(persist('sagi-trips',next)){saved=next;renderRatecons();toast('Rate confirmation attached to saved trip.');}};
 for(const b of $('rateconList').querySelectorAll('[data-delete]'))b.onclick=async()=>{if(!confirm('Remove this document from this browser? Your trip estimates will remain.'))return;const id=b.dataset.delete,next=saved.map(s=>s.rateconId===id?{...s,rateconId:null}:s);if(!persist('sagi-trips',next))return;saved=next;try{await docOp('readwrite',s=>s.delete(id));if(window.activeRateconId===id)window.setActiveRatecon(null);if(reviewingRatecon?.id===id){reviewingRatecon=null;$('rateconReview').hidden=true;}renderRatecons();toast('Document removed.');}catch(e){toast(e.message)}};
 }catch(e){$('rateconList').textContent=e.message;}}
window.renderRatecons=renderRatecons;
const renderSavedWithoutRatecon=renderSaved;
renderSaved=function(){renderSavedWithoutRatecon();$('savedList').querySelectorAll('.trip-card').forEach((card,i)=>{const trip=saved[i];if(!trip?.rateconId)return;const b=document.createElement('button');b.textContent='Open rate confirmation ↗';b.onclick=async()=>{try{const doc=await docOp('readonly',s=>s.get(trip.rateconId));if(!doc){toast('Document not found on this device. Upload it again.');return}tab('ratecons');showRatecon(doc);$('rateconReview').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast(e.message)}};card.querySelector('.actions').prepend(b);});};
window.addEventListener('pagehide',()=>{rateconURLs.forEach(u=>URL.revokeObjectURL(u));rateconURLs=[];});
